"use client";

import { memo, useId, useRef, type ReactNode } from "react";
import { X } from "lucide-react";
import { LazyMotion, domAnimation, useAnimationControls, useReducedMotion } from "motion/react";
import * as m from "motion/react-m";
import { Button } from "./button";
import { Card } from "./card";

interface SheetProps {
  side?: "top" | "right" | "bottom" | "left";
  triggerLabel?: string;
  title?: string;
  description?: string;
  children?: ReactNode;
  className?: string;
}

export const Sheet = memo(function Sheet({
  side = "bottom",
  triggerLabel = "Open sheet",
  title = "Make yourself at home",
  description = "A little space for your next action. Press Escape or close to return.",
  children,
  className = "",
}: SheetProps = {}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const id = useId();
  const animation = useAnimationControls();
  const textAnimation = useAnimationControls();
  const reducedMotion = useReducedMotion();
  const closing = useRef(false);

  const horizontal = side === "left" || side === "right";
  const translate = (value: string | number) =>
    horizontal ? { x: value, y: 0 } : { x: 0, y: value };
  const offset =
    side === "left" || side === "top"
      ? "calc(-100% - var(--spacing) * 4)"
      : "calc(100% + var(--spacing) * 4)";
  const placement = {
    bottom: "inset-x-0 bottom-4 top-auto mx-auto max-h-[85dvh] w-full sm:max-w-xl",
    top: "inset-x-0 top-4 bottom-auto mx-auto max-h-[85dvh] w-full sm:max-w-xl",
    left: "top-1/2 bottom-auto left-4 right-auto -translate-y-1/2 max-h-[calc(100dvh-var(--spacing)*8)] w-[calc(100%-var(--spacing)*8)] sm:max-w-md",
    right:
      "top-1/2 bottom-auto right-4 left-auto -translate-y-1/2 max-h-[calc(100dvh-var(--spacing)*8)] w-[calc(100%-var(--spacing)*8)] sm:max-w-md",
  }[side];
  const expandedWidth = horizontal ? "calc(100% - var(--spacing) * 8)" : "100%";
  const expandedHeight = horizontal ? "calc(100dvh - var(--spacing) * 8)" : "auto";

  const textVariants = {
    hidden: {
      opacity: 0,
      y: reducedMotion ? 0 : "calc(var(--spacing) * 3)",
      transition: { duration: reducedMotion ? 0 : 0.12 },
    },
    visible: { opacity: 1, y: 0 },
  };

  const openSheet = async () => {
    const sheet = dialog.current;
    if (!sheet || sheet.open) return;
    textAnimation.set("hidden");
    animation.set({ x: 0, y: 0, opacity: 0, width: expandedWidth, height: expandedHeight });
    // Motion renders on the next frame; measure the natural size immediately on reopen.
    sheet.style.width = expandedWidth;
    sheet.style.height = expandedHeight;
    sheet.showModal();
    const { width, height } = sheet.getBoundingClientRect();
    const handle = sheet.querySelector<HTMLElement>("[data-slot=sheet-handle]")!;
    const spacing = parseFloat(getComputedStyle(handle)[horizontal ? "width" : "height"]);
    sheet.style.overflow = "hidden";
    animation.set({
      width: reducedMotion ? width : Math.min(spacing * 36, width),
      height: reducedMotion ? height : Math.min(spacing * 16, height),
      ...translate(reducedMotion ? 0 : offset),
      opacity: 0,
    });
    await animation.start({
      ...translate(0),
      opacity: 1,
      transition: reducedMotion ? { duration: 0 } : { type: "spring", stiffness: 280, damping: 30 },
    });
    if (!sheet.open || closing.current) return;
    await animation.start({
      width,
      height,
      transition: { duration: reducedMotion ? 0 : 0.35, ease: [0.22, 1, 0.36, 1] },
    });
    if (!sheet.open || closing.current) return;
    animation.set({ width: expandedWidth, height: expandedHeight });
    sheet.style.overflow = "";
    void textAnimation.start("visible");
  };

  const closeSheet = async () => {
    const sheet = dialog.current;
    if (!sheet?.open || closing.current) return;
    closing.current = true;
    animation.stop();
    textAnimation.stop();
    sheet.style.overflow = "hidden";
    const { width, height } = sheet.getBoundingClientRect();
    const handle = sheet.querySelector<HTMLElement>("[data-slot=sheet-handle]")!;
    const spacing = parseFloat(getComputedStyle(handle)[horizontal ? "width" : "height"]);
    animation.set({ width, height });
    await textAnimation.start("hidden");
    await animation.start({
      width: reducedMotion ? width : Math.min(spacing * 36, width),
      height: reducedMotion ? height : Math.min(spacing * 16, height),
      transition: { duration: reducedMotion ? 0 : 0.3, ease: [0.22, 1, 0.36, 1] },
    });
    await animation.start({
      ...translate(reducedMotion ? 0 : offset),
      opacity: 0,
      transition: { duration: reducedMotion ? 0 : 0.2, ease: "easeIn" },
    });
    sheet.close();
    sheet.style.overflow = "";
    closing.current = false;
  };

  return (
    <LazyMotion features={domAnimation} strict>
      <div className={className}>
        <Button type="button" aria-haspopup="dialog" onClick={() => void openSheet()}>
          {triggerLabel}
        </Button>
        <m.dialog
          ref={(node) => {
            dialog.current = node;
            node?.setAttribute("closedby", "any");
          }}
          initial={{ ...translate(offset), opacity: 0 }}
          animate={animation}
          onCancel={(event) => {
            event.preventDefault();
            void closeSheet();
          }}
          aria-labelledby={`${id}-title`}
          aria-describedby={`${id}-description`}
          data-side={side}
          className={`fixed my-0 max-w-none overflow-x-hidden overflow-y-auto rounded-lg surface-raised p-0 text-card-foreground backdrop:bg-black/60 ${placement}`}
        >
          {horizontal && (
            <div
              aria-hidden="true"
              data-slot="sheet-handle"
              className={`pointer-events-none absolute top-1/2 z-10 h-10 w-1 -translate-y-1/2 bg-muted-foreground/40 ${side === "left" ? "right-2" : "left-2"}`}
            />
          )}
          <Card
            title=""
            description=""
            className={`relative max-w-none! border-0! ${horizontal ? "min-h-full" : ""}`}
          >
            <m.div
              className="absolute right-3 top-3 z-10"
              initial="hidden"
              animate={textAnimation}
              variants={{
                hidden: { opacity: 0, visibility: "hidden" },
                visible: { opacity: 1, visibility: "visible" },
              }}
              transition={{ duration: reducedMotion ? 0 : 0.15 }}
            >
              <Button
                type="button"
                variant="ghost"
                aria-label="Close sheet"
                onClick={() => void closeSheet()}
                className="size-11 p-0!"
              >
                <X aria-hidden="true" size={24} />
              </Button>
            </m.div>
            {!horizontal && (
              <div
                aria-hidden="true"
                data-slot="sheet-handle"
                className="mx-auto mb-6 h-1 w-10 bg-muted-foreground/40"
              />
            )}
            <m.div
              initial="hidden"
              animate={textAnimation}
              variants={{
                hidden: {},
                visible: { transition: { staggerChildren: reducedMotion ? 0 : 0.18 } },
              }}
            >
              <m.div
                className="flex items-start justify-between gap-4 pr-12"
                variants={textVariants}
                transition={{ duration: reducedMotion ? 0 : 0.45, ease: "easeOut" }}
              >
                <h2 id={`${id}-title`} className={"typography-section-title"}>
                  {title}
                </h2>
              </m.div>
              <m.p
                variants={textVariants}
                transition={{ duration: reducedMotion ? 0 : 0.45, ease: "easeOut" }}
                id={`${id}-description`}
                className={`mt-3 typography-body`}
              >
                {description}
              </m.p>
              {children && (
                <m.div
                  className="mt-6"
                  variants={textVariants}
                  transition={{ duration: reducedMotion ? 0 : 0.45, ease: "easeOut" }}
                >
                  {children}
                </m.div>
              )}
            </m.div>
          </Card>
        </m.dialog>
      </div>
    </LazyMotion>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & ((ComponentProps<"button"> & { href?: never }) | (ComponentProps<"a"> & { href: string }));

export function buttonClassName(variant: ButtonProps["variant"] = "primary", className = "") {
  const styles = {
    primary:
      "[--button-color:var(--color-emerald-400)] [--button-top:var(--color-emerald-300)] [--button-stroke-top:var(--color-emerald-200)] [--button-stroke-bottom:var(--color-emerald-700)] text-neutral-950",
    secondary: "[--button-color:var(--secondary)] text-secondary-foreground",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "[--button-color:var(--destructive)] text-destructive-foreground",
    outline:
      "[--button-color:var(--background)] [--button-top:var(--background)] [--button-bottom:var(--muted)] [--button-stroke-top:var(--border)] [--button-stroke-bottom:color-mix(in_srgb,var(--foreground)_25%,var(--border))] text-foreground hover:[--button-top:var(--muted)]",
  };
  const surface =
    variant === "ghost"
      ? ""
      : "border border-transparent [background:linear-gradient(to_bottom,var(--button-top,color-mix(in_srgb,var(--button-color)_88%,white)),var(--button-bottom,var(--button-color)))_padding-box,linear-gradient(to_bottom,var(--button-stroke-top,color-mix(in_srgb,var(--button-color)_65%,white)),var(--button-stroke-bottom,color-mix(in_srgb,var(--button-color)_65%,black)))_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.12),0_4px_8px_-2px_rgb(0_0_0/0.18)] hover:[--button-top:color-mix(in_srgb,var(--button-color)_78%,white)]";
  return `inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-5 py-2 text-sm font-semibold  transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 ${surface} ${styles[variant] ?? styles.primary} ${className}`;
}

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const classes = buttonClassName(variant, className);

  if (props.href !== undefined) {
    return (
      <a className={classes} {...props}>
        {children}
      </a>
    );
  }

  return (
    <button type="button" className={classes} {...props}>
      {children}
    </button>
  );
});

import { memo, type ComponentProps, type ReactNode } from "react";
import { cn } from "cn";

// Legacy content props remain supported for existing consumers.
const cardSizes = {
  sm: "gap-4 px-4 py-4",
  md: "gap-6 px-6 py-6",
} as const;

type CardProps = {
  size?: keyof typeof cardSizes;
  title?: string;
  description?: string;
  footer?: ReactNode;
} & (
  | ({ as?: "article" } & Omit<ComponentProps<"article">, "title">)
  | ({ as: "a" } & Omit<ComponentProps<"a">, "title">)
);

const Card = memo(function Card({
  title,
  description,
  children,
  footer,
  className,
  size = "md",
  ...props
}: CardProps) {
  const hasLegacyContent = Boolean(title || description || footer);
  const classes = cn(
    "group/card flex w-full max-w-sm flex-col rounded-lg surface-raised text-base leading-7",
    "outline-ring focus-visible:outline-[length:var(--focus-ring-width,2px)] focus-visible:outline-offset-[var(--focus-ring-offset,2px)]",
    "[a&]:transition-colors [a&]:duration-[var(--duration-fast,150ms)] [a&]:ease-out [a&]:hover:[--surface-bottom:var(--muted)] motion-reduce:transition-none",
    cardSizes[size],
    className,
  );
  const content = (
    <>
      {(title || description) && (
        <CardHeader>
          {title && <CardTitle>{title}</CardTitle>}
          {description && <CardDescription>{description}</CardDescription>}
        </CardHeader>
      )}
      {hasLegacyContent ? children && <CardContent>{children}</CardContent> : children}
      {footer && <CardFooter>{footer}</CardFooter>}
    </>
  );
  if (props.as === "a") {
    const { as: Tag, ...anchorProps } = props;
    return (
      <Tag data-slot="card" data-size={size} className={classes} {...anchorProps}>
        {content}
      </Tag>
    );
  }
  const { as: Tag = "article", ...articleProps } = props;
  return (
    <Tag data-slot="card" data-size={size} className={classes} {...articleProps}>
      {content}
    </Tag>
  );
});

const CardHeader = memo(function CardHeader({ className, ...props }: ComponentProps<"header">) {
  return (
    <header
      data-slot="card-header"
      className={cn(
        "grid auto-rows-min items-start gap-x-4 gap-y-2 has-[[data-slot=card-action]]:grid-cols-[1fr_auto]",
        className,
      )}
      {...props}
    />
  );
});

const CardTitle = memo(function CardTitle({ className, ...props }: ComponentProps<"h3">) {
  return (
    <h3 data-slot="card-title" className={cn("typography-section-title", className)} {...props} />
  );
});

const CardDescription = memo(function CardDescription({
  className,
  ...props
}: ComponentProps<"p">) {
  return (
    <p
      data-slot="card-description"
      className={cn("col-start-1", "typography-body", className)}
      {...props}
    />
  );
});

const CardAction = memo(function CardAction({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
});

const CardContent = memo(function CardContent({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="card-content" className={className} {...props} />;
});

const CardFooter = memo(function CardFooter({ className, ...props }: ComponentProps<"footer">) {
  return (
    <footer
      data-slot="card-footer"
      className={cn("flex items-center border-t border-border pt-4", className)}
      {...props}
    />
  );
});

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };
